    ('meeting_note', 'LinkedIn postlarını gözden geçirme ve Reels video aracı arama', 'UBT hafta sonu hazırladığı LinkedIn postlarına bakacak; 5 saniyelik video üreten bir araç bulursa Reels içeriğiyle "boğacak" (yoğun içerik üretecek).', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'LinkedIn postlarını gözden geçirme ve Reels video aracı arama', 1420),
    ('meeting_note', 'Önce profil sayfaları çalışılacak', 'UBT Stripe yerine önce profil işine el atacağını söyledi; profillerin içeriden/dışarıdan görünümlerini çözecek, listeleme işi ("kolay") sonraya bırakıldı, tablar aktarılıyor.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'Önce profil sayfaları çalışılacak', 1430),
    ('meeting_note', 'Featured/reklam vitrini ikinci adımda tasarlanacak', 'Sekmeden girişte featured ve öne çıkarılan (reklam veren) profillerin kullanıcıyı karşılaması fikri kabul gördü; genel mimari bittikten sonra ince iş olarak ele alınacak.', '7 Temmuz 2026', 'Atanmadi', 'Tamamlandi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'Featured/reklam vitrini ikinci adımda tasarlanacak', 1440),
    ('meeting_note', 'Higgsfield Pro''ya geçiş tamamlanacak', 'UBT Higgsfield''ı Pro plana çekmeye çalışıyor; fiyat 29/25/35$ arasında değişiyor (vazgeçince indirim taktiği). En düşük teklifi bulup satın alacak, olmazsa ertesi gün yapacak.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'reklam-modeli', 'Higgsfield Pro''ya geçiş tamamlanacak', 1450),
    ('meeting_note', 'Seedance video aracı denenecek', 'Burak Kling''i denedi; araçların hepsinde "yatay verme" (dikey format vermeme) sorunu var. UBT önerilen Seedance''i deneyecek; yatay riskine dikkat etmesi söylendi.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'Seedance video aracı denenecek', 1460),
    ('meeting_note', 'Burak''ın status cevapları toplantı öncesi incelenecek', 'UBT, Burak''ın status sorularına verdiği cevapları ve kendi yazdıklarının üzerine eklediklerini inceleyecek; kafasında yol haritası (harita) belirleyecek.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'audit-kayitlari', 'Burak''ın status cevapları toplantı öncesi incelenecek', 1470),
    ('meeting_note', 'neo4 aboneliği iptal edildi, refund istenecek', 'Kaynağı hatırlanmayan bir neo4 ödemesi fark edildi; UBT aboneliği iptal etti (geçen ay da uğraşmıştı) ve ertesi gün refund talep edecek. Makbuz corteqs mailine gelmiş; Burak''a gelirse UBT''ye iletecek.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'neo4 aboneliği iptal edildi, refund istenecek', 1480),
    ('meeting_note', 'Metunic ile Doruk.net fiyat karşılaştırması istendi', 'UBT, Burak''tan domain sağlayıcıları Metunic ve Doruk.net''in karşılaştırmasını yapmasını istedi; Burak ertesi gün yapacağını söyledi (acelesi yok denildi).', '7 Temmuz 2026', 'Burak', 'Tamamlandi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'Metunic ile Doruk.net fiyat karşılaştırması istendi', 1490),
    ('meeting_note', '%10 kâr payı teklifinin analizi 1 hafta içinde', 'desiremap''ten %10 kâr payı teklifi var, Stripe altyapısı kullanılacak; Burak win-win mi, riskli mi, kâra mı zarara mı olduğunu 1 hafta içinde analiz edecek ve toplantıda konuşulacak.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', '%10 kâr payı teklifinin analizi 1 hafta içinde', 1500),
    ('meeting_note', 'Domain yenileme/taşıma geçiş süreci netleştirilecek', 'Burak domainlerin yenilenme tarihlerinin geldiğini, taşınanların nerede yenileneceğinin belirsiz olduğunu ve 30 gün önceden bildirim mailini anlamadığını söyledi; geçiş süreci UBT''de, Burak''ın ödemesi/ödememesi gerekenler ona bildirilecek; her şey tek yerden, az maliyetle takip edilmek isteniyor.', '7 Temmuz 2026', 'UBT', 'Tamamlandi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'Domain yenileme/taşıma geçiş süreci netleştirilecek', 1510),
    ('meeting_note', 'Doruk''taki tüm otomatik yenilemeler kapatılacak', 'UBT''nin talimatıyla Burak Doruk''taki yenilemeleri komple kapatacak; taşınma 2-3 gün içinde tamamlanınca Doruk aboneliği komple iptal edilecek (taşınan domainler Doruk''tan zaten düşecek).', '7 Temmuz 2026', 'Burak', 'Tamamlandi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'Doruk''taki tüm otomatik yenilemeler kapatılacak', 1520),
    ('meeting_note', 'Kalan domainler için Namecheap taşıması yeniden başlatılacak', 'UBT henüz taşınmamış domainler için aynı gün Namecheap''e tekrar taşıma başlatacak; com.tr''lerin taşındığını belirtti (kısmi kanıt), taşınma bitince Doruk kapatılacak.', '7 Temmuz 2026', 'UBT', 'Tamamlandi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'Kalan domainler için Namecheap taşıması yeniden başlatılacak', 1530),
    ('meeting_note', 'Sitelerin hostingleri tek serverda toplanacak', 'UBT sitelerin hosting/kod dosyalarının nerede olduğunu sordu; hepsinin tek bir serverda toplanıp ayrı ayrı hosting ücreti ödenmemesi önerildi.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'Sitelerin hostingleri tek serverda toplanacak', 1540),
    ('meeting_note', 'Domain/hosting envanter tablosu hazırlanıp Drive''a konacak', 'UBT tüm domain/hosting durumunu (ne yapıldı, ne yapılacak) gösteren detaylı bir analiz tablosu/doküman çıkaracak; karar gereği doküman Drive''a konacak ve domain-hosting takibi artık oradan yapılacak.', '7 Temmuz 2026', 'UBT', 'Tamamlandi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'Domain/hosting envanter tablosu hazırlanıp Drive''a konacak', 1550),
    ('meeting_note', 'Yarına kadar domain takip paneli hazırlanacak', 'Barış, ertesi günkü toplantıda üzerinden geçebilmek için Burak''ın domain takip işini (panelini) yarına kadar halledeceğini söyledi.', '7 Temmuz 2026', 'UBT', 'Tamamlandi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'Yarına kadar domain takip paneli hazırlanacak', 1560),
    ('meeting_note', 'Namecheap''ten gelen maillere bakılacak', 'Burak, Namecheap''ten gelen mailleri Barış''ın kontrol etmesini istedi.', '7 Temmuz 2026', 'UBT', 'Tamamlandi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'audit-kayitlari', 'Namecheap''ten gelen maillere bakılacak', 1570),
    ('meeting_note', 'Panele yenilenme tarihleri eklenecek', 'Burak, domain paneline yenilenme (renewal) tarihleri gibi bilgilerin de eklenmesini önerdi; Barış''ın paneli bu yönde geliştirmesi bekleniyor.', '7 Temmuz 2026', 'UBT', 'Tamamlandi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'Panele yenilenme tarihleri eklenecek', 1580),
    ('meeting_note', 'Doruk''taki domain otomatik yenilemeleri kapatılacak', 'Barış, gerekli transfer maillerinin atıldığını, Burak''ın Doruk''taki tüm domain yenilemelerini kapatabileceğini söyledi; 3-4 gün sonra transferler yürürlüğe girince hosting taşıması başlayacak.', '7 Temmuz 2026', 'Burak', 'Tamamlandi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'Doruk''taki domain otomatik yenilemeleri kapatılacak', 1590),
    ('meeting_note', 'Paneldeki hosting sütunu doldurulacak', 'Barış, hangi sitenin nerede host edildiğini bilip taşımayı planlayabilmek için Burak''tan paneldeki hosting sütununu doldurmasını istedi; site olmayanlara "site yok" yazılabilir (satır 3213).', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'Paneldeki hosting sütunu doldurulacak', 1600),
    ('meeting_note', 'turksdiaspora.net GoDaddy transfer kodu alınacak', 'Barış, Burak''tan GoDaddy''ye girip turksdiaspora.net için "transfer to other registrar" kodunu almasını istedi; transfer edilmemiş tek domain bu görünüyordu, birkaç gün beklenmesine karar verildi.', '7 Temmuz 2026', 'Burak', 'Tamamlandi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'topluluk-yonetimi', 'turksdiaspora.net GoDaddy transfer kodu alınacak', 1610),
