    ('meeting_note', 'Profil işi çözülecek, Burak sosyal medya çalışacak', 'Burak o gün ve ertesi gün sosyal medya çalışacağını, Barış ise (CorteQS''te) profil işini çözmeyi umduğunu söyledi.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'Profil işi çözülecek, Burak sosyal medya çalışacak', 1730),
    ('meeting_note', 'QS sitesi çekilip Doruk aboneliği komple kapatılacak', 'Barış, aynı gün QS (Qualtron Sinclair) sitesini çekip Doruk tarafını komple kapatmayı planladı.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'QS sitesi çekilip Doruk aboneliği komple kapatılacak', 1740),
    ('meeting_note', 'payaltr site dosyalarına erişim Seren''e sorulacak', 'payaltr sitesini Seren yaptığı için Barış, Burak''tan Seren''e "payaltr sitesinin dosyalarına nereden erişebilirim" diye sormasını istedi; Burak sordu (satır 3526).', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'influencer-partnerlikleri', 'payaltr site dosyalarına erişim Seren''e sorulacak', 1750),
    ('meeting_note', 'payaltr Cloudflare DNS şifresi temin edilecek', 'payaltr''ın domain yöneticisi Cloudflare çıktı; Barış DNS ayarları için Cloudflare hesabının şifresini istedi. Burak Seren''den istedi; sonradan şifre olmadığı, Google hesabıyla + telefon OTP ile girildiği öğrenildi (satır 3596-3599).', '7 Temmuz 2026', 'Burak', 'Tamamlandi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'kullanici-kisitlamalari', 'payaltr Cloudflare DNS şifresi temin edilecek', 1760),
    ('meeting_note', 'Kitap çevirisi için DeepL API araştırılacak', 'Barış, kitabını İngilizceye çeviren Burak''a işini kolaylaştırması için DeepL API''yi araştırmasını söyledi; gerekirse ertesi gün anlatacak.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'Kitap çevirisi için DeepL API araştırılacak', 1770),
    ('meeting_note', 'Instagram slider ve story''lere destek verilecek', 'Burak, molalarda Instagram''a yeni gelen slider ve story paylaşımlarına destek (beğeni/etkileşim) atılmasını istedi.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'reklam-modeli', 'Instagram slider ve story''lere destek verilecek', 1780),
    ('meeting_note', 'Seren''e payaltr hosting/FTP bilgisi sorulacak', 'UBT, payaltr.com''un Doruknet''te FTP ile mi yapıldığını ve site dosyalarının nerede olduğunu Seren''e sordurmasını istedi; Cloudflare''de site görünmüyordu, Plesk/FTP şifresi gerekiyordu.', '7 Temmuz 2026', 'Burak', 'Tamamlandi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'Seren''e payaltr hosting/FTP bilgisi sorulacak', 1790),
    ('meeting_note', 'Doruknet şifre maili gelirse haber verilecek', 'UBT, Doruknet''ten password (şifre sıfırlama) maili gelirse Burak''ın hemen haber vermesini istedi.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'Doruknet şifre maili gelirse haber verilecek', 1800),
    ('meeting_note', 'Siteleri inceleyip revizyon isteklerini yazacak', 'Tüm siteler yenileriyle değişiyor ve her admin panelinde revizyon istekleri bölümü var; Burak siteleri tek tek inceleyip revizyonları (metinleri GPT''den geçirip) yazacak, UBT aktaracak.', '7 Temmuz 2026', 'Burak', 'Tamamlandi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'audit-kayitlari', 'Siteleri inceleyip revizyon isteklerini yazacak', 1810),
