    ('meeting_note', 'NOT: Instagram vibe referans hesapları', 'turks.diaspora ve mariapudero hesapları içerik referansı olarak paylaşıldı; mariapudero 5 postla 4500 takipçi ve yüksek izlenme almış, bu vibe''ın yakalanması hedefleniyor.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'reklam-modeli', 'NOT: Instagram vibe referans hesapları', 2310),
