    ('meeting_note', 'KARAR: İçerik stratejisi reel ağırlıklı olacak', 'Normal postlar 10 günde 200-400 görüntülenirken reel 2-3 saatte 158 görüntülenme aldı; bu veriye dayanarak "reel yağdırmak lazım" kararı verildi.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'reklam-modeli', 'KARAR: İçerik stratejisi reel ağırlıklı olacak', 2330),
    ('meeting_note', 'KARAR: MVP 0.5 lansmanı aceleye getirilmeyecek', 'UBT MVP 0.5''i sadece "ekleme" özelliğiyle aynı gün çıkarmak istedi ama 19 Mayıs''taki gibi boşa efor olmaması için acele edilmemesi kararlaştırıldı; UBT mevcut durumun ufak bir kısmını yeni sisteme taşımayı deneyecek.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'KARAR: MVP 0.5 lansmanı aceleye getirilmeyecek', 2340),
    ('meeting_note', 'NOT: Yarın Paraguay-Türkiye maçı var', 'Maç yayını viral kampanyası ve işletme kayıt hamlesi için zamanlama bağlamı olarak paylaşıldı.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'NOT: Yarın Paraguay-Türkiye maçı var', 2350),
