    ('meeting_note', 'KARAR: 25 dolarlık Google Android Developer hesabı onaylandı', 'UBT tek seferlik 25$ Google Android Developer Account ücreti için onay istedi; Burak onay kodunu iletip "ok" dedi.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'kullanici-kisitlamalari', 'KARAR: 25 dolarlık Google Android Developer hesabı onaylandı', 2380),
    ('meeting_note', 'KARAR: Android süreci önce almanya101''de öğrenilecek', 'Play Store yayınlama süreci önce almanya101.de uygulamasında öğrenilip sonra CorteQS''e uygulanacak.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'KARAR: Android süreci önce almanya101''de öğrenilecek', 2390),
    ('meeting_note', 'NOT: Reel formatı posttan 164 kat etkili', 'Instagram verisine göre 1 post görüntülemesine karşılık 164 reel görüntülemesi var; üretime reeller üzerinden devam edilecek.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'reklam-modeli', 'NOT: Reel formatı posttan 164 kat etkili', 2400),
    ('meeting_note', 'KARAR: Cadde toplantısı cumartesi/pazartesiye ertelendi', 'Cadde bugün konuşulmayacak; UBT önce kupa kampanya ayarlamaları, Cadde guide incelemesi ve toplantıda geçen diğer konulara eğilecek, toplantı cumartesi veya pazartesi yapılacak.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Cadde toplantısı cumartesi/pazartesiye ertelendi', 2410),
    ('meeting_note', 'KARAR: Ana sayfaya kampanya CTA''sı konulacak', 'Kullanıcı captiondaki linki aramasın diye ana sayfaya Dünya Kupası kampanyası için CTA eklenmesine karar verildi.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Ana sayfaya kampanya CTA''sı konulacak', 2420),
    ('meeting_note', 'KARAR: Ülke odaklı pazarlama: 1 hafta Almanya, 1 hafta USA', '"Çok geneliz" tespitiyle scrape + doküman + reklam üçlüsüyle hedef odaklı takipçi/üye artırma stratejisine geçilecek; işletmeler scrape edilecek, Almanya ile başlanacak.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'KARAR: Ülke odaklı pazarlama: 1 hafta Almanya, 1 hafta USA', 2430),
    ('meeting_note', 'NOT: Cadde feed admin paneli gibi görünüyor', 'Burak''a göre Cadde feed''i klasik sosyal feed görünümünde değil; UBT''ye göre backend %50, frontend %25 hazır ve çok değişiklik gerekecek.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'NOT: Cadde feed admin paneli gibi görünüyor', 2440),
    ('meeting_note', 'NOT: Kart kaydı yapıldı, henüz ödeme yok', '(Muhtemelen developer hesabı için) kart kaydı yapıldı, para çekilmedi; Burak doğrulama kodunu iletti.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'NOT: Kart kaydı yapıldı, henüz ödeme yok', 2450),
    ('meeting_note', 'KARAR: Önce genel/empati kuran reels stratejisi', 'Doğrudan CorteQS tanıtımı yerine önce mass içerik: "Almanya''da yaşam", "Zimbabve''de kültür", "Fas''ta su sıkıntısı" gibi empati kuran genel reellerle başlanacak.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'reklam-modeli', 'KARAR: Önce genel/empati kuran reels stratejisi', 2460),
    ('meeting_note', 'KARAR: CorteQS Android app sessiz yayın stratejisi', 'almanya101 app başvurusunun hemen ardından CorteQS başvurusu yapılacak; 14 tester''ın 12 gün kullanım şartını contributor''lar karşılayacak. Uygulama yayınlanınca duyurulmayacak, database''ler oturunca duyurulacak.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'KARAR: CorteQS Android app sessiz yayın stratejisi', 2470),
    ('meeting_note', 'NOT: eng.corteqs.net eski durumda', 'İngilizce site eng.corteqs.net güncel değil; yenilenip yenilenmeyeceği henüz belirsiz.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'NOT: eng.corteqs.net eski durumda', 2480),
    ('meeting_note', 'NOT: Haber çekme ücretsiz, kaynak arama ileride paralı', 'Haber çekimi bedava; kaynak arama ileride ücretli olacak ama tamamı 50 Euro''yu geçmez, şu an bedava krediyle çalışıyor.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'NOT: Haber çekme ücretsiz, kaynak arama ileride paralı', 2490),
    ('meeting_note', 'KARAR: SEO içerik kapsamı: 10 ülke, 3 konu, 30 makale', 'SEO içerik planı için 10 ülke seçildi; 3 konu üzerinden toplam 30 makale üretilecek.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'reklam-modeli', 'KARAR: SEO içerik kapsamı: 10 ülke, 3 konu, 30 makale', 2500),
    ('meeting_note', 'KARAR: Mobil uygulamaya başlanacak, önce Android', 'Claude aboneliği varken mobil app geliştirmesine başlanacak; ilk hedef Android sürümü.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'KARAR: Mobil uygulamaya başlanacak, önce Android', 2510),
    ('meeting_note', 'NOT: Landing page UI/UX denetimi: genel puan 6,8/10', 'Claude ile ana sayfanın kapsamlı UI/UX denetimi yapıldı (henüz kod değiştirilmedi). Marka etkisi 8, dönüşüm odaklılık 5,5, erişilebilirlik 5,5, SEO altyapısı 8 puan aldı.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'NOT: Landing page UI/UX denetimi: genel puan 6,8/10', 2520),
    ('meeting_note', 'KARAR: ChatGPT landing analizi onaylandı, uygulanacak', 'Burak analizi "çok iyi ve isabetli" bularak onayladı; UBT bulguları uygulayacağını söyledi. Karar: landing "teknolojik ama minimalist" olacak. Not: Spindora SEO/GEO''ya bakıyor, bu analiz ChatGPT''den.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'audit-kayitlari', 'KARAR: ChatGPT landing analizi onaylandı, uygulanacak', 2530),
    ('meeting_note', 'KARAR: WhatsApp''a beta üyelik daveti mesajı çıkılacak', 'Üye olmayanları üyeliğe yönlendiren bir beta duyuru mesajı atılması kararlaştırıldı; UBT CTO olarak yazacak, teknik çalışmalardan bahsedip beta geri bildirimlerinin değerli olduğu vurgulanacak ve geri bildirim için bir kanal belirtilecek.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: WhatsApp''a beta üyelik daveti mesajı çıkılacak', 2540),
    ('meeting_note', 'KARAR: Beta duyuru metninin son hali onaylandı', '"CorteQS Beta Yenilendi" WhatsApp duyurusunun revize hali (üye olmayan üyelerimiz + geri bildirimlerin gruptan/özelden paylaşılması eklenmiş versiyon) Burak''ın önerileriyle güncellendi ve onaylandı; referral''lı ilk taslağa veto verildi.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'audit-kayitlari', 'KARAR: Beta duyuru metninin son hali onaylandı', 2550),
    ('meeting_note', 'NOT: Admin referral sekmesi çalışmıyor', 'Burak admin panelindeki referral sekmesinin komple kapalı göründüğünü, sadece şablon olduğunu bildirdi; beta kullanıcılarına arkadaş çağırma referralı verme fikri şimdilik veto edildi (kapsam küçük tutulacak), UBT bakacağını söyledi.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'NOT: Admin referral sekmesi çalışmıyor', 2560),
    ('meeting_note', 'KARAR: CorteQS Engine (eng.corteqs.net) park edildi', 'Çok fazla servis barındıran eng.corteqs.net''in iptal edilip yerine daha küçük bir girişim önerildi; şimdilik "park edelim" kararı alındı, ileride konuşulacak (hazır ama geliştirme gerekiyor, şu an için erken).', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'KARAR: CorteQS Engine (eng.corteqs.net) park edildi', 2570),
    ('meeting_note', 'NOT: MVP düzeltme listesi Proje Yönetimi''nde tutuluyor', 'Burak düzeltme maddelerini "Proje Yönetimi > MVP düzeltmeler" altında topluyor ve eklemeye devam ediyor; UBT bu listeden maddeleri eritecek.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'NOT: MVP düzeltme listesi Proje Yönetimi''nde tutuluyor', 2580),
    ('meeting_note', 'NOT: Clemta maili geldi, Stripe önü açıldı', 'Clemta''dan mail geldi; Stripe başvurusu için bürokratik engel kalmadı. Ücret tahsil edilebilecek ürünler ve akışlar gözden geçirilip hazırlıklar tamamlanabilir.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'NOT: Clemta maili geldi, Stripe önü açıldı', 2590),
    ('meeting_note', 'KARAR: CorBot ve Jukebox IP düzenlemesi', 'WhatsApp bot-CorBot (ODTÜ ile kurulursa UBT ortak) ve Jukebox (ayrı spin-off olursa UBT şimdilik yok) solo geliştirilebilir IP''ler olarak CorteQS''e süresiz ve koşulsuz lisanslanacak; CorteQS bunlar üzerinden ticaret yaparsa satış ücreti ödeyecek.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'KARAR: CorBot ve Jukebox IP düzenlemesi', 2600),
    ('meeting_note', 'KARAR: Stripe-uyumlu plan toplantısı yarın 16:00-17:00', 'Stripe friendly ürün/ücretlendirme planı için ertesi gün İstanbul saatiyle 16:00-17:00 arası toplantı yapılması kararlaştırıldı.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Stripe-uyumlu plan toplantısı yarın 16:00-17:00', 2610),
    ('meeting_note', 'NOT: LinkedIn şifresi paylaşıldı, sayfada paylaşım yok', 'UBT''nin önceden açtığı CorteQS LinkedIn profilinin şifresi ("CorteQS0626!") paylaşıldı; henüz orada paylaşım yapılmıyor, hesap atıl durumda.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'NOT: LinkedIn şifresi paylaşıldı, sayfada paylaşım yok', 2620),
    ('meeting_note', 'NOT: Seren Cadde lansman videosu hazırlıyor', 'Seren, Cadde lansmanı üzerinde çalışıyor; yaklaşık 1.4 dakikalık iddialı bir master video yakında çıkacak.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'NOT: Seren Cadde lansman videosu hazırlıyor', 2630),
    ('meeting_note', 'NOT: Haiku modeli yazım hatası üretiyor, Opus''a geçildi', 'Burak kitabının edisyonunda Haiku''nun her iki cümlede bir yazım hatası yaptığını, Opus''a geçince düzeldiğini bildirdi; UBT de Opus''a geçmesini onayladı.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'audit-kayitlari', 'NOT: Haiku modeli yazım hatası üretiyor, Opus''a geçildi', 2640),
    ('meeting_note', 'NOT: Claude ile Amazon Seller paneli yönetimi araştırılacak', 'Burak Claude''un Amazon Sellers paneline bağlanıp yönetip yönetemeyeceğini sordu; UBT MCP olup olmadığına bakacağını, ancak Amazon''un izin vermeyeceği için tam verimli olmayacağı görüşünde olduğunu söyledi.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'kullanici-kisitlamalari', 'NOT: Claude ile Amazon Seller paneli yönetimi araştırılacak', 2650),
    ('meeting_note', 'NOT: Serkan Hoca''nın diaspora etkinlik daveti — temkinli yaklaşım', 'Serkan Hoca''nın Türk diasporası platformu, webinarlar ve AI vizyonu konulu etkinlik duyurusu paylaşıldı; her iki ortak da kişiye güvenmediklerini ifade etti, temkinli durulacak.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'reklam-modeli', 'NOT: Serkan Hoca''nın diaspora etkinlik daveti — temkinli yaklaşım', 2660),
