    ('meeting_note', 'NOT: Mobil app demo linki paylaşıldı', 'App''in ilk sürümü Netlify linkinde (benevolent-axolotl-2a7c96.netlify.app) paylaşıldı; telefon tarayıcısından açılması gerekiyor, Burak zorlanarak açtı ve "fena değil" dedi.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'kullanici-kisitlamalari', 'NOT: Mobil app demo linki paylaşıldı', 2680),
    ('meeting_note', 'KARAR: Sistem duyurusu hero''da korunacak', 'Sistem olayı postlarda duyurulmakla birlikte sitenin hero bölümünde de geçmesinin iyi olduğuna ve korunmasına karar verildi.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'KARAR: Sistem duyurusu hero''da korunacak', 2690),
    ('meeting_note', 'KARAR: Landing değişiklikleri pilot sayfada denenecek', 'UBT önerileri doğrudan canlıya almak yerine ek bir pilot sayfa çıkaracak; değişiklikler onun üzerinde denenip sonra canlıya alınacak.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'KARAR: Landing değişiklikleri pilot sayfada denenecek', 2700),
    ('meeting_note', 'KARAR: Her kategoriye kendi landing sayfası (LP)', 'Menü sekmelerinde her kategorinin (işletme/dernek vb.) kendi LP''sinin olmasına karar verildi; kullanıcının "benim ekranım neye benzeyecek" sorusuna placeholder kartlarla cevap verilecek — corteqs+''taki mantığın aynısı.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'KARAR: Her kategoriye kendi landing sayfası (LP)', 2710),
    ('meeting_note', 'NOT: Deep research veri setlerinin Drive konumu', 'Deep research sonuçlarındaki veri setleri Google Drive''da "DATA SETLER" klasöründe (drive.google.com/drive/folders/1NwCUFkzp9oiKVXGsqGHemKr1gwbeIdW1); UBT bu verileri kullanacak.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'kullanici-kisitlamalari', 'NOT: Deep research veri setlerinin Drive konumu', 2720),
    ('meeting_note', 'KARAR: Google AI (Gemini) aboneliği iptal edildi', 'UBT''nin sorması üzerine Burak kararsız kaldıktan sonra Gemini aboneliğini iptal etti (refund ve cancellation submit edildi); 30 Haziran''a kadar kullanılabilecek. UBT bir aylık başka video tool denemesini önerdi.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'kullanici-kisitlamalari', 'KARAR: Google AI (Gemini) aboneliği iptal edildi', 2730),
    ('meeting_note', 'NOT: UI tasarım dili için referans site tartışması', 'Burak British Airways/PayPal/Amex gibi siteleri UI esin kaynağı önerdi; UBT bunların aşırı fonksiyonel olduğunu (DHL denemesi kötü sonuçlanmıştı), Vodafone.com desktop''ın iyi bir referans olduğunu söyledi.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'NOT: UI tasarım dili için referans site tartışması', 2740),
    ('meeting_note', 'NOT: "Lovable vibe coding belirgin" kritiği geldi', 'Burak''ın toplantıda yaptığı sunumda sitenin Lovable/vibe coding görünümünün çok belirgin olduğu kritiği geldi; UBT butonların vs. zaten baştan yapıldığını, Lovable''dan bir şey kalmadığını savundu.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'NOT: "Lovable vibe coding belirgin" kritiği geldi', 2750),
    ('meeting_note', 'KARAR: Yarın toplantı — sabah 10-11 veya akşam 17-18', 'Ertesi gün toplantı yapılması kararlaştırıldı; Burak İstanbul''a geçeceği için sabah 10-11 veya akşam 17-18 (TSİ) saatleri önerildi.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'KARAR: Yarın toplantı — sabah 10-11 veya akşam 17-18', 2760),
