    ('meeting_note', 'KARAR: Kampanya subscription açılışına ertelendi', 'Erken kampanyaların tutmaması nedeniyle influencer kampanyası Cadde ve site bitip subscription açıldığında yapılacak; o zamana kadar her gün birkaç reel ve post paylaşılacak.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Kampanya subscription açılışına ertelendi', 2910),
