    ('meeting_note', 'KARAR: Şirketleşmede iki aşamalı standart yaklaşım', 'Clemta maili sonrası şimdilik standart/şablon çözümle ilerlenecek, para kazanılınca geniş versiyona convert edilecek; böylece süreç hızlanacak.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'KARAR: Şirketleşmede iki aşamalı standart yaklaşım', 2930),
    ('meeting_note', 'NOT: 10 yeni soru-cevap tool''u implemente ediliyor', '15-20 soruluk, scoring ve database tabanlı araçlar geliştiriliyor (örnek: almanya101.de/sigorta-secim); şimdilik ana sayfalara linklenmeyecek, yeri implementasyondan sonra belirlenecek.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'NOT: 10 yeni soru-cevap tool''u implemente ediliyor', 2940),
    ('meeting_note', 'NOT: Türk finansçıyla iş birliği toplantısı', 'CorteQS ve Almanya101 araçlarını kullanmak ve üye sağlamak isteyen 20 yıllık bir Türk finansçıyla ertesi gün 16:30''da toplantı yapılacak; çıktılar Burak''a aktarılacak.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'NOT: Türk finansçıyla iş birliği toplantısı', 2950),
    ('meeting_note', 'KARAR: Beta üretim sırası belirlendi', 'Sıra: 1-Profiller+admin panelleri, 1.5-Ana sayfa top menü+kategorik dağılım, 2-Taşınma Motoru+toollar, 3-Search Bar, 4-Cadde, 5-Stripe entegrasyon/test, 6-Marketing Plan, 7-Cadde Lansman, 8-Full MVP (features, ilan yönetimi, subscription), 9-Site Lansman, 10-Yarışmalar.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Beta üretim sırası belirlendi', 2960),
    ('meeting_note', 'NOT: QS''e başvuranlar listesi paylaşıldı', 'Burak, QS''e başvuranların bulunduğu Google Sheets dosyasının linkini paylaştı.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'kullanici-kisitlamalari', 'NOT: QS''e başvuranlar listesi paylaşıldı', 2970),
