    ('meeting_note', 'NOT: Test hesabı incelenmek üzere paylaşıldı', 'UBT, tool ve kullanıcı/admin incelemesi için experimental2@corteqs.net test hesabını şifresiyle birlikte Burak''a verdi.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'audit-kayitlari', 'NOT: Test hesabı incelenmek üzere paylaşıldı', 2990),
    ('meeting_note', 'KARAR: Sosyal medya otomasyonu ertelendi, önce manuel içerik', 'Post paylaşımları şimdilik otomasyonsuz, copy-paste ile manuel yapılacak; otomasyon çok sonra gelecek. Gerekçe: otomasyon kolay ama içerik üretimi zor.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'KARAR: Sosyal medya otomasyonu ertelendi, önce manuel içerik', 3000),
    ('meeting_note', 'KARAR: Backlink gelir projesi başlatıldı (Batuhan ile)', 'UBT, Batuhan ile domain footer''larına backlink ekleyerek aylık 4-6K gelir hedefleyen projeye başladı. Amaç AI (Claude vb.) giderlerini bu gelirle karşılamak; Burak''ın tüm domainlerine ihtiyaç var.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Backlink gelir projesi başlatıldı (Batuhan ile)', 3010),
    ('meeting_note', 'NOT: Burak''ın 20 domaini var, 17''si backlink''e uygun', 'Burak''ın toplam ~20 domaini olduğu ortaya çıktı (corteqs.net dahil 18 kullanılabilir). Kaan-şaman ve QS domainleri hariç 17 tanesi backlink projesinde kullanılabilir.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'NOT: Burak''ın 20 domaini var, 17''si backlink''e uygun', 3020),
    ('meeting_note', 'KARAR: Backlink geliri üçe bölünecek, iki pay kasaya', 'Batuhan''ın müşterilerinden 3-4 site için ~2500 TL ödeme gelecek; Burak''ın domainleri de eklenince gelir 3''e bölünecek ve 2 pay şirket kasasına gidecek. Burak "good deal" diyerek onayladı.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Backlink geliri üçe bölünecek, iki pay kasaya', 3030),
    ('meeting_note', 'NOT: UBT tanıdıklara 4-5 web sitesi yapıyor', 'UBT yan iş olarak 4-5 web sitesi geliştiriyor, 2''si için sembolik ücret alacak. Bu tanıdıkların müşteri bulmasıyla iş modelinin büyümesi bekleniyor.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'NOT: UBT tanıdıklara 4-5 web sitesi yapıyor', 3040),
    ('meeting_note', 'NOT: ODTUGATHER: yeni mezun işe yerleştirme fikri', 'Burak''ın ODTÜ mezunlar topluluğu, her yıl mezun olan 3-4 bin kişiyi işe yerleştirme sekmesi (ODTUGATHER) için araştırmaya başladı. UBT teknik destek verebileceğini söyledi; ayrıntılar sonra konuşulacak.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'NOT: ODTUGATHER: yeni mezun işe yerleştirme fikri', 3050),
    ('meeting_note', 'NOT: Doruknet yenileme maliyeti 9K TL, çok pahalı', 'Burak''a 9K TL''lik bir yenileme faturası geldi; iki taraf da aşırı bulup ödeme/altyapı değişikliğine karar verdi. Bu, tüm domain taşıma operasyonunu tetikledi.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'NOT: Doruknet yenileme maliyeti 9K TL, çok pahalı', 3060),
    ('meeting_note', 'KARAR: Altyapı taşıma: Namecheap + Supabase + Zoho, tek panel', 'Tüm domainler Namecheap''e taşınacak, database ücretsiz Supabase olacak, mailler Zoho''ya alınacak; her şey tek panelden yönetilecek (Burak tek yer tercihini onayladı). Siteler önce aynen taşınacak, dizayn değişikliği ileride yapılacak; UBT komple el attı.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'audit-kayitlari', 'KARAR: Altyapı taşıma: Namecheap + Supabase + Zoho, tek panel', 3070),
    ('meeting_note', 'KARAR: com.tr domainleri için ucuz alternatif: metunic', 'com.tr''ler Namecheap dışında tutulacak, onlar için daha ucuz yer bulunacak (metunic.com.tr seçildi). Gerekçe: Doruknet gereksiz pahalı ve artısı yok.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'KARAR: com.tr domainleri için ucuz alternatif: metunic', 3080),
    ('meeting_note', 'NOT: Network Solutions''ta unutulmuş domain bulundu', 'Burak''ın Network Solutions''ta alıp unuttuğu bir domain daha ortaya çıktı; GoDaddy''de de domainler var. UBT Network Solutions için corteqssocial hesabı oluşturdu.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'influencer-partnerlikleri', 'NOT: Network Solutions''ta unutulmuş domain bulundu', 3090),
    ('meeting_note', 'NOT: Namecheap kayıt adresi: Corteqs Global LLC Delaware', 'Namecheap hesabının kayıt adresi olarak Corteqs Global LLC''nin Delaware (8 The Green STE D, Dover) adresi girildi.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'kullanici-kisitlamalari', 'NOT: Namecheap kayıt adresi: Corteqs Global LLC Delaware', 3100),
    ('meeting_note', 'KARAR: Doruknet''ten her şey taşınabilir; kaan+saman hariç LP yok', 'UBT''nin "almamam gerekenleri yaz" sorusuna Burak "her şeyi alabilirsin" dedi. Sadece kaanakcakanat ve samanakcakanat domainlerine landing page veya backlink yapılmayacak.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'KARAR: Doruknet''ten her şey taşınabilir; kaan+saman hariç LP yok', 3110),
    ('meeting_note', 'NOT: Burak''ın kişisel sitesi iş+blog olacak, footer backlink konabilir', 'Burak, kişisel domaininin işler ve kişisel blog içeren bireysel web sitesi olacağını, footer''ına da backlink konabileceğini belirtti.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'audit-kayitlari', 'NOT: Burak''ın kişisel sitesi iş+blog olacak, footer backlink konabilir', 3120),
    ('meeting_note', 'KARAR: timingfinance.com drop edildi, devam etmeyecek', 'Burak timingfinance.com domainini drop ettiğini ve projeyi devam ettirmeyeceğini söyledi; transfer kapsamı dışında bırakıldı.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'reklam-modeli', 'KARAR: timingfinance.com drop edildi, devam etmeyecek', 3130),
    ('meeting_note', 'KARAR: or-ge.com.tr drop edildi, otomatik yenileme kapatıldı', 'Burak or-ge.com.tr domainini devam ettirmeme kararı aldı; otomatik yenileme UBT tarafından hemen kapatıldı.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'KARAR: or-ge.com.tr drop edildi, otomatik yenileme kapatıldı', 3140),
    ('meeting_note', 'NOT: Stripe onayı için sitede canlı ödeme akışı gerekli', 'Burak, Stripe başvurusunda inceleme ekibinin sitede somut bir hizmet satın alma/ödeme akışını test edeceğini, doküman eksiği olmadığını açıkladı. Subscription/marketplace henüz devrede olmadığı için başvuru bekletiliyordu; taraflar arasında bilgi kopukluğu olduğu anlaşıldı.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'NOT: Stripe onayı için sitede canlı ödeme akışı gerekli', 3150),
    ('meeting_note', 'KARAR: Clemta''nın pahalı paketi reddedildi, standart devam', 'Clemta ana sözleşme, operating contract ve ortaklık metinleri için fazla para isteyince standart yolla devam edilmesine karar verilmişti; bu karar teyit edildi.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Clemta''nın pahalı paketi reddedildi, standart devam', 3160),
    ('meeting_note', 'NOT: Founding 1000 için ücret tahsil etme fikri', 'Stripe testine somut ödeme göstermek için Founding 1000 üyeliği üzerinden gerçek ücret tahsil edilebileceği fikri ortaya atıldı.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'NOT: Founding 1000 için ücret tahsil etme fikri', 3170),
    ('meeting_note', 'NOT: experimental3 için yeni workflow tanımlanıyor', 'experimental3 kapsamında yeni bir workflow tanımlanıyor; Stripe incelemesinde bu akış izletilecek, ayrıntılar sonra konuşulacak.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'NOT: experimental3 için yeni workflow tanımlanıyor', 3180),
    ('meeting_note', 'NOT: Stripe mock demo kılavuzu paylaşıldı', 'UBT, experimental3@corteqs.net demo kullanıcısıyla sahte Stripe ödeme akışının (MockStripeCheckout) adım adım sunum kılavuzunu paylaştı. Ödeme demo modunda; gerçek işlem/kart verisi hiçbir yere yazılmıyor, ücret sabiti ServiceRequestForm.tsx içindeki SERVICE_REQUEST_FEE.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'NOT: Stripe mock demo kılavuzu paylaşıldı', 3190),
    ('meeting_note', 'KARAR: Üyelik ücretsiz, hizmet aşamasında subscription', 'Burak''ın önerisi: subscription zorunluluğu friction yaratır; işletme/danışman ücretsiz üye olsun, hizmet talebine cevap/yazışma-mesaj aşamasında subscription (veya tekil ödeme) devreye girsin.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Üyelik ücretsiz, hizmet aşamasında subscription', 3200),
    ('meeting_note', 'NOT: Mock akış son kullanıcıdan ücret alıyor', 'Burak, mevcut mock ödeme akışında ücretin işletmeden değil son kullanıcıdan (talebi oluşturandan) alındığına dikkat çekti; gelir modeli tartışmasına girdi.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'NOT: Mock akış son kullanıcıdan ücret alıyor', 3210),
    ('meeting_note', 'KARAR: Monetizasyon 1-2 ay ertelendi, önce 1K üye', 'UBT, para isteme/ücretlendirme işlerinin 1-2 ay ertelenmesini istedi; önce 1000 üye hedefi, sonra gelir konuları.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Monetizasyon 1-2 ay ertelendi, önce 1K üye', 3220),
    ('meeting_note', 'KARAR: Hero için metinsiz video şartı (veto)', 'UBT metinli hero videosunu veto etti: hero''ya yalnız ~10 saniyelik metinsiz, light/abstract video konulacak; metinli videolar ileride başka yerde kullanılacak. Stripe mockup''ı ise onaylandı ("stripe mockup ok").', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Hero için metinsiz video şartı (veto)', 3230),
    ('meeting_note', 'NOT: İşbirliği toplantıları ve gelir fırsatları', 'Bir toplantı yapıldı: karşı taraf Almanya101 toollarını kullanmak istiyor, UBT ileride bu toolları CorteQS''e yönlendirecek. Ağustos başı influencer bağlantılı biriyle toplantı var; bir finansçı toollarda kendi sistemini promote ettirip üye kazandırma karşılığı ödeme yapacak; backlink geliri de mümkün.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'NOT: İşbirliği toplantıları ve gelir fırsatları', 3240),
    ('meeting_note', 'KARAR: Topluluk güncellemesi profiller bitince yapılacak', 'Gruba ve contributor''lara "neler yaptık, neler geliyor" güncellemesi (muhtemelen videolu) verilecek; profiller bitip "girin claim edin" denebilecek aşama beklenerek yapılması kararlaştırıldı.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'KARAR: Topluluk güncellemesi profiller bitince yapılacak', 3250),
    ('meeting_note', 'NOT: Tanıtım için ekran kaydı alındı', 'Burak üründen kısa bir ekran kaydı aldı; biraz kısa ama ileride montajlanmak üzere saklanacak.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'NOT: Tanıtım için ekran kaydı alındı', 3260),
    ('meeting_note', 'NOT: Namecheap ve Supabase hesap bilgileri paylaşıldı', 'UBT, Burak''a Namecheap (kullanıcı: bakcakanat) ve Supabase (buraksupabase@corteqs.net) giriş bilgilerini WhatsApp üzerinden iletti; şifre formatı sonu iki yıldız olarak standardize edildi, diğer hesaplar girildikçe değiştirilecek. (Not: şifrelerin düz metin paylaşımı güvenlik riski.)', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'NOT: Namecheap ve Supabase hesap bilgileri paylaşıldı', 3270),
    ('meeting_note', 'NOT: Zoho hazır, Supabase kişisel site için', 'Zoho kurulumu tamam (panel: mailadmin.zoho.eu, posta: mail.zoho.com); Burak''a açılan Supabase hesabı kişisel web sayfası için, şu an aksiyon gerekmiyor. Zoho''dan Gmail''e yönlendirme var ama okundu-durumu senkronu yok.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'NOT: Zoho hazır, Supabase kişisel site için', 3280),
