    ('meeting_note', 'NOT: Namecheap iadesi henüz gelmedi', 'Kart kontrolünde refund görünmüyor ("nope"); Burak "prosese girdiyse sorun yok" dedi. Burak ayrıca Namecheap şifresini resetledi.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'audit-kayitlari', 'NOT: Namecheap iadesi henüz gelmedi', 3310),
    ('meeting_note', 'KARAR: getstaketurk.com bırakılıyor', 'Burak getstaketurk.com domainini drop etme kararı aldı; UBT onayladı, backlink için tutmaya değmeyeceği konuşuldu.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'audit-kayitlari', 'KARAR: getstaketurk.com bırakılıyor', 3320),
    ('meeting_note', 'KARAR: Kullanılmayan abonelikler otomatik yenileme kapatılarak bırakılacak', 'Otomatik yenileme kapatılınca ödemenin durduğu teyit edildi; buna dayanarak kapalı/kullanılmayan abonelikler drop edilecek.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Kullanılmayan abonelikler otomatik yenileme kapatılarak bırakılacak', 3330),
    ('meeting_note', 'NOT: Namecheap şifresi değiştirildi ve sohbette paylaşıldı', 'Burak Namecheap şifresini değiştirdiğini söyledi ve yeni şifreyi WhatsApp''ta düz metin olarak paylaştı (satır 2715; güvenlik açısından not edilmeli).', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'NOT: Namecheap şifresi değiştirildi ve sohbette paylaşıldı', 3340),
    ('meeting_note', 'KARAR: Stripe önce Founding 1000''e bağlanacak, kampanyalar sonra', 'Kampanyaları Stripe''a bağlamanın erken olduğuna birlikte karar verildi; ilk Stripe bağlantısı Founding 1000 için yapılacak.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Stripe önce Founding 1000''e bağlanacak, kampanyalar sonra', 3350),
    ('meeting_note', 'KARAR: Lovable UI mantığıyla devam: kart/detay kart, bireyseller liste', 'Lovable''daki UI mantığından devam edilecek; Bireysel hariç profiller mikro profil kartı / detay kartı, bireysel profiller liste olarak gösterilecek.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'KARAR: Lovable UI mantığıyla devam: kart/detay kart, bireyseller liste', 3360),
    ('meeting_note', 'KARAR: Genel arama sonuçları önce tek formatta kart olarak listelenecek', 'Aynı isimde farklı profil türlerinin (ör. "Mahmut" hem firma hem kişi hem doktor) tek aramada çıkması sorunu için önce tüm sonuçlar tek formatta (kart) listelenecek; kategoriye özel mantık iteratif olarak ikinci adımda düşünülecek.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'KARAR: Genel arama sonuçları önce tek formatta kart olarak listelenecek', 3370),
    ('meeting_note', 'NOT: Video aracı durumu ve MiniMax alternatifi', 'Ücretli video aracı üyeliği sorgulandı; Higgsfield üyeliği o an yoktu, video için Gemini kullanılıyordu. UBT alternatif olarak https://agent.minimax.io/ linkini video denemesi amacıyla paylaştı.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'NOT: Video aracı durumu ve MiniMax alternatifi', 3380),
    ('meeting_note', 'NOT: Backlink gelir beklentisi (Batu 10 site yapıyor)', 'Batu backlink için 10 site yapıyor; UBT''nin siteleri için ~2500 teklif edilmişti, Burak''ın siteleri de eklenince artabilir; o kanaldan ortalama 8K gelir konuşuluyor (tek seferlik ağırlıklı).', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'NOT: Backlink gelir beklentisi (Batu 10 site yapıyor)', 3390),
    ('meeting_note', 'KARAR: Backlink geliri ortak giderlere aktarılacak', 'UBT backlinklerden gelecek parayı ikisi adına, şimdiye kadar yapılan ortak harcamaları kompanse etmek için doğrudan gider kasasına aktaracak; Burak kabul etti.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Backlink geliri ortak giderlere aktarılacak', 3400),
    ('meeting_note', 'KARAR: Aylık gider bütçesi ~150 dolar olarak belirlendi', 'Aylık gider planı netleşti: 100$ Claude + 25$ video aracı + 3-5$ Zoho + 20$ server ≈ 150$ (~7500 TL, kişi başı ~4K TL); başka kalıcı gider olmayacak.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'KARAR: Aylık gider bütçesi ~150 dolar olarak belirlendi', 3410),
    ('meeting_note', 'NOT: 165 üyeye sıfır reklamla ulaşıldı; 1 ay sonra full pazarlama', 'Siteye "tamam, gümbür gümbür gelsinler" denecek hale gelmesi için ~1 ay daha gerekiyor; sonrasında full PR/marketing ve 1:1 görüşmelerle büyüme planlanıyor. Neredeyse sıfır reklamla 165 üyeye ulaşıldı; Burak sponsored içerik için bütçe ayırdı.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'reklam-modeli', 'NOT: 165 üyeye sıfır reklamla ulaşıldı; 1 ay sonra full pazarlama', 3420),
    ('meeting_note', 'KARAR: Cuma (3 Temmuz) 13:00 Katar saati Zoom toplantısı fikslendi', 'Haftalık toplantı 3 Temmuz Cuma 13:00 (Katar) için Zoom''da ayarlandı ve link sabitlendi; bu toplantıda kurallar konuşulacak, cuma sabahı topikler kısaca sohbete yazılacak.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'KARAR: Cuma (3 Temmuz) 13:00 Katar saati Zoom toplantısı fikslendi', 3430),
    ('meeting_note', 'NOT: Zoho ödemesini UBT yapacak, hesaba yazılacak', 'Zoho''dan ~2.5-3 euro çekilecek; ödemeyi UBT yapacak ve tutar ortak hesaplaşmaya UBT lehine not edilecek.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'NOT: Zoho ödemesini UBT yapacak, hesaba yazılacak', 3440),
    ('meeting_note', 'KARAR: desiremap için tercihen yeni LLC açılacak', 'desiremap gelirini CorteQS LLC üzerinden mi almak yoksa yeni LLC mi açmak sorusuna Burak "tercihen yeni" dedi; gerekçe hesap ayrımı ve exit kolaylığı. Yeni LLC maliyeti cepten ~1-1.5K dolar.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: desiremap için tercihen yeni LLC açılacak', 3450),
    ('meeting_note', 'NOT: Tahsilat modeli ve eyalet bildirimi gerekliliği', 'Model olarak şirketin tahsilatı yapıp işletme bedeli alması makul bulundu; sektör ve site adı şirket adından farklı olduğu için eyalete (DBA/faaliyet adı) bildirim yapılması gerekiyor.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'NOT: Tahsilat modeli ve eyalet bildirimi gerekliliği', 3460),
    ('meeting_note', 'KARAR: Shaman/HCD domainleri 2028''e kadar Network Solutions''ta kalacak', 'Qualtron ve Payal domainleri Doruk''ta; shamanlife.com ve humanconsciousnessdecoded.com Network Solutions''ta bulundu ve geçen yıl 2028''e kadar yenilenmiş — 2028''e kadar orada kalacak, sonra taşınacak.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'influencer-partnerlikleri', 'KARAR: Shaman/HCD domainleri 2028''e kadar Network Solutions''ta kalacak', 3470),
    ('meeting_note', 'NOT: Maskot toplantısı transcriptinin konumu bildirildi', 'UBT Maskot toplantısının transcriptini istedi; Burak kaydın "Toplantı kayıtları satır 19 / June 8" konumunda olduğunu bildirdi.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'kullanici-kisitlamalari', 'NOT: Maskot toplantısı transcriptinin konumu bildirildi', 3480),
    ('meeting_note', 'KARAR: Domain/host takibi Excel yerine web panelden yapılacak', 'Barış, domain ve hosting işlemlerinin Excel yerine kendi web sitesinden vereceği bir link (panel) üzerinden takip edileceğine karar verdi.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'KARAR: Domain/host takibi Excel yerine web panelden yapılacak', 3490),
    ('meeting_note', 'NOT: Turhost daveti gelmedi, giriş bilgileri paylaşıldı', 'Turhost invitation Barış''a ulaşmadı; Burak bunun yerine turhost hesabının giriş bilgilerini (ubterzioglu@gmail.com) doğrudan paylaştı.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'NOT: Turhost daveti gelmedi, giriş bilgileri paylaşıldı', 3500),
