    ('meeting_note', 'NOT: Burak''ın sitelerinin teknoloji envanteri', 'Burak''ın siteleri: payaltr WordPress, shamanlife muhtemelen WordPress, humancons muhtemelen Sefa yapımı, qualtron Wix; Barış taşıma planı için bu envanteri çıkardı.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'veritabani-tasarimi', 'NOT: Burak''ın sitelerinin teknoloji envanteri', 3530),
    ('meeting_note', 'KARAR: Burak''ın siteleri yeni teknolojiyle yeniden yapılacak', 'Barış, WordPress/Wix sitelerini komple devralıp teknolojiyi değiştireceğine karar verdi; yeni site görünümleri önce oluşturulacak, Burak onay verince geçilecek.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'audit-kayitlari', 'KARAR: Burak''ın siteleri yeni teknolojiyle yeniden yapılacak', 3540),
    ('meeting_note', 'KARAR: Toplantı pazartesiye ertelendi, önce özet hazırlanacak', 'Barış iş yoğunluğu nedeniyle toplantıyı erteleyip Burak''ın işleri ve CorteQS işlerinin durumunu özetleyerek pazar/pazartesi üzerinden konuşmayı önerdi; Burak kabul etti.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'KARAR: Toplantı pazartesiye ertelendi, önce özet hazırlanacak', 3550),
    ('meeting_note', 'KARAR: Burak''ın siteleri Barış''ın GitHub hesabında açılacak', 'Barış, iş kolaylığı için Burak''ın tüm web sitelerini kendi GitHub hesabı altında açacağına karar verdi; ileride başka geliştirici gelirse yetkiyi kendisi verecek.', '7 Temmuz 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Burak''ın siteleri Barış''ın GitHub hesabında açılacak', 3560),
    ('meeting_note', 'KARAR: Pazar toplantısında ilerleme, beta UI/UX ve Cadde konuşulacak', 'Burak, Zoom toplantısını pazara kaydırdı; gündem: genel ilerleme, betanın UI/UX''i ve Cadde. Burak ayrıca tabloya yorumlarını yazdığını ve Stripe''ın eklendiğini belirtti.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Pazar toplantısında ilerleme, beta UI/UX ve Cadde konuşulacak', 3570),
    ('meeting_note', 'NOT: Mezun toplulukları için Lovable prototipleri paylaşıldı', 'Burak, sınıf arkadaşları için yaptığı kolej-memory-weave ve gather-ai-weave Lovable uygulamalarını paylaştı; Barış kendi lisesi için calcom.club''ı yaptığını, bitince framework olarak birlikte satabileceklerini ve mobil uyarlama yapabileceğini söyledi.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'mvp-hedefleri', 'NOT: Mezun toplulukları için Lovable prototipleri paylaşıldı', 3580),
    ('meeting_note', 'KARAR: Mezun platformu framework olarak satılacak, CorteQS''e kaynak olacak', 'Barış, mezun topluluğu sitesini (calcom.club yapısını) framework olarak satmayı ve ODTÜ''lülerden aylık 250 TL abonelikle CorteQS''e gelir kaynağı yaratmayı önerdi; Barış backend+mobil+web app verecek, Burak işletecek.', '7 Temmuz 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'rezervasyon-sistemi', 'KARAR: Mezun platformu framework olarak satılacak, CorteQS''e kaynak olacak', 3590),
    ('meeting_note', 'KARAR: 1 Ağustos''a kadar görev takibi Burak''ta', 'Karar: CorteQS + ODTÜ + hosting işlerinin takibi 1-2 hafta (1 Ağustos''a kadar) Burak''ta olacak; Burak her hafta kısa deadline''lı to-do listesi çıkaracak, Barış uygulayıcı olacak. Command Center yerine task-force usulü çalışılacak.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'audit-kayitlari', 'KARAR: 1 Ağustos''a kadar görev takibi Burak''ta', 3600),
    ('meeting_note', 'KARAR: Burak''ın odağı CorteQS, diğer işler ikincil', 'Burak, odağının CorteQS''te olduğunu, yol haritası ve to-do''nun belli olduğunu, diğer her şeyin ikincil olduğunu netleştirdi.', '7 Temmuz 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '7 Temmuz 2026', 'ekip-ve-isbirligi', 'KARAR: Burak''ın odağı CorteQS, diğer işler ikincil', 3610),
