    ('meeting_note', 'KARAR: Seren''in videosu Cadde lansmanında kullanılacak', 'Seren''in yaptığı Cadde videosu (1,5 dakikalık landmark video) beğenilmese de emek verildiği için Cadde lansmanında yayınlanmasına karar verildi; başka video yapmaya engel değil.', '2 Ağustos 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '2 Ağustos 2026', 'mvp-hedefleri', 'KARAR: Seren''in videosu Cadde lansmanında kullanılacak', 6520),
    ('meeting_note', 'NOT: Canva Dream Lab kullanım talimatı', 'Barış, Canva''da doğru yerin sol üstteki üç noktadan girilen Dream Lab olduğunu, format/style seçilmesini ve emin olunmayan durumda style olarak "smart" seçilmesini anlatıyor.', '2 Ağustos 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '2 Ağustos 2026', 'ekip-ve-isbirligi', 'NOT: Canva Dream Lab kullanım talimatı', 6530),
    ('meeting_note', 'KARAR: Tools görselleri için GPT''lik promptlar Burak''a gönderilecek', 'Burak, tools için "bunları GPT''de sen yap" denilen promptların kendisine gönderilmesi yöntemini öneriyor; iş bölümü bu şekilde yapılacak.', '2 Ağustos 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '2 Ağustos 2026', 'veritabani-tasarimi', 'KARAR: Tools görselleri için GPT''lik promptlar Burak''a gönderilecek', 6540),
    ('meeting_note', 'KARAR: Toplantı 18 Temmuz sabah 11 TSİ olarak planlandı', 'Burak öğleden sonrası karışık olduğu için ertesi günkü toplantı sabah 11 TSİ olarak kararlaştırıldı (sonradan 18 Temmuz''da akşam 5-6''ya kaydı).', '2 Ağustos 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '2 Ağustos 2026', 'ekip-ve-isbirligi', 'KARAR: Toplantı 18 Temmuz sabah 11 TSİ olarak planlandı', 6550),
    ('meeting_note', 'KARAR: Claude/MCP görselleri kötü; GPT veya Canva kullanılacak', 'Claude''un free MCP''lerle ürettiği görseller çok kötü bulundu; Barış Canva''da basacağını söylüyor, Burak görselde hâlâ iyi olan GPT''yi öneriyor.', '2 Ağustos 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '2 Ağustos 2026', 'ekip-ve-isbirligi', 'KARAR: Claude/MCP görselleri kötü; GPT veya Canva kullanılacak', 6560),
