    ('meeting_note', 'NOT: Rakip inceleme: globalturks.com.tr ve London Turks uygulaması', 'Barış, globalturks.com.tr ve London Turks Android uygulamasını paylaştı; uygulama Almanya''ya kapalı, global yapılmamış olması eleştiriliyor (rakip/emsal analizi).', '2 Ağustos 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '2 Ağustos 2026', 'audit-kayitlari', 'NOT: Rakip inceleme: globalturks.com.tr ve London Turks uygulaması', 6590),
    ('meeting_note', 'NOT: Admin ve profillerde değişiklik yapıldı, güncellemeler okunmalı', 'Barış admin paneli ve profillerde bazı değişiklikler yaptı, güncellemeler sayfasına işledi; Burak''ın incelemesi isteniyor. Ayrıca görsellerden Higgsfield generic prompt ile 5 saniyelik video denemeleri yapılacak.', '2 Ağustos 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '2 Ağustos 2026', 'audit-kayitlari', 'NOT: Admin ve profillerde değişiklik yapıldı, güncellemeler okunmalı', 6600),
    ('meeting_note', 'KARAR: MVP düzeltme listesi Drive''dan admin paneline taşınacak', 'MVP düzeltmeler şu an Drive''da text dosyası olarak duruyor; Barış bunun artık admin panelinden yönetilmesine karar verip düzenlemeye başladı.', '2 Ağustos 2026', 'UBT', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '2 Ağustos 2026', 'mvp-hedefleri', 'KARAR: MVP düzeltme listesi Drive''dan admin paneline taşınacak', 6610),
    ('meeting_note', 'KARAR: Prompt üretimine pazartesi başlanacak', 'Burak''ın promptlardan görsel üretimi pazartesiye ertelendi; Barış görselleri 4 kez iyileştirdi, sonuçları görecek, beğenmezse 2-3 iyileştirme daha yaptıracak, sonra 288 prompt hazır olacak.', '2 Ağustos 2026', 'Burak', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '2 Ağustos 2026', 'reklam-modeli', 'KARAR: Prompt üretimine pazartesi başlanacak', 6620),
    ('meeting_note', 'NOT: 288 prompt Reddit+LinkedIn+Instagram için randomize planlandı', '288 prompt, postlarla birlikte Reddit, LinkedIn ve Instagram''da kullanılacak; tarihe göre randomize sıralı ve aynı konu art arda gelmeyecek şekilde başlıkları karıştırılmış durumda.', '2 Ağustos 2026', 'Atanmadi', 'Baslanmadi', 5, null, false, 'meeting_notes', 'WA', '2 Ağustos 2026', 'mvp-hedefleri', 'NOT: 288 prompt Reddit+LinkedIn+Instagram için randomize planlandı', 6630),
